#pragma once
// The p-multigrid V-cycle 7 -> 3 -> 1 (cellwise::PMultigrid) with its per-iteration
// kernels generated by MARSIR, from three PTX files in marsir-mlir/generated/:
//   pmg_sm90.ptx                  Chebyshev steps, masked residual copies, transfers,
//                                 dot products (test/dss_gpu_pipeline.py --pmg);
//   hl_cellwise_p3_sm90.ptx,      the operator at p = 3 and 1 from the same operator spec
//   hl_cellwise_p1_sm90.ptx       as the p = 7 kernel, with the schedule for small
//                                 elements (test/hl_gpu_pipeline.py p --cellwise: many
//                                 elements per block, a thread per output point).
// The p = 7 operator is the solve's own. Setup (diagonals, power iteration) and the
// optional BoomerAMG coarse solve keep their current code.
//
// MarsirPmg puts the V-cycle behind the preconditioner interface of the Krylov
// solvers (the hand cellwise::bicgstab and the generated marsir::bicgstab).

#include "backend/distributed/unstructured/fem/mars_cvfem_ho_basis.hpp"
#include "backend/distributed/unstructured/marsir/mars_marsir_ptx_cellwise.hpp"
#include "backend/distributed/unstructured/marsir/mars_marsir_ptx_operator.hpp"
#include "backend/distributed/unstructured/solvers/mars_cellwise_pmg.hpp"

#include <thrust/device_vector.h>

#include <string>
#include <vector>

namespace mars {
namespace marsir {

class PmgPtx : public CellwisePtx, public cellwise::PmgKernels {
public:
    // G3, G1: the p = 3 and p = 1 metrics of PMultigrid.
    PmgPtx(const std::string& dir, const cellwise::UnstructuredTopology& T, const double* G3, const double* G1)
        : CellwisePtx(dir + "/pmg_sm90.ptx", 7), T_(T), G3_(G3), G1_(G1),
          op3_(dir + "/hl_cellwise_p3_sm90.ptx", 3), op1_(dir + "/hl_cellwise_p1_sm90.ptx", 1)
    {
        const char* kinds[3] = {"first0", "first", "next"};
        const int degrees[3] = {7, 3, 1};
        for (int i = 0; i < 3; ++i)
            for (int k = 0; k < 3; ++k)
                cheb_[i][k] = function(std::string("cheb_") + kinds[k] + "_p" + std::to_string(degrees[i]));
        masked_[0] = function("masked_copy_p7");
        masked_[1] = function("masked_copy_p3");
        restrict73_ = function("interp_4x8");
        restrict31_ = function("interp_2x4");
        prolong37_[0] = function("interp_8x4");
        prolong37_[1] = function("interp_8x4_add");
        prolong13_[0] = function("interp_4x2");
        prolong13_[1] = function("interp_4x2_add");
        dots_[0] = function("pmg_dots_p7_az");
        dots_[1] = function("pmg_dots_p7_zz");
        dots_[2] = function("pmg_dots_p7_az_zz");
        operators(3, op3m_);
        operators(1, op1m_);
        interpolation(cellwise::interpolation<7, 3>(), i73_, i73t_);
        interpolation(cellwise::interpolation<3, 1>(), i31_, i31t_);
        MARS_CELLWISE_CK(cudaDeviceSynchronize());   // the pageable uploads above
    }

    void apply(int p, const double* u, double* y, cudaStream_t s) override
    {
        const Matrices& m = p == 3 ? op3m_ : op1m_;
        (p == 3 ? op3_ : op1_).apply(u, raw(m.btil), raw(m.dtil), raw(m.w), raw(m.d), p == 3 ? G3_ : G1_, y, T_.local, s);
    }

    void chebyshev(int p, int kind, const double* b, const double* y, const double* ghost, const double* diag, double* d,
                   double* x, double c1, double c2, const cellwise::ElementList& set, cudaStream_t s) override
    {
        if (set.count == 0) return;
        const long long m = values(p), L = T_.local * m;
        std::vector<Arg> a = topology_args(b, ghost, T_, set, m);
        a.insert(a.begin() + 2, Arg{y ? y : b, L});   // (b, ghost, y, elements, tables...)
        a.push_back(vec(T_.counting));
        a.push_back(vec(T_.edge_dirichlet));
        a.push_back(vec(T_.vert_dirichlet));
        a.push_back({diag, L});
        a.push_back({d, L});
        a.push_back({x, L});
        launch(cheb_[degree_index(p)][kind], a, set.count, s, {}, {c1, c2});
    }

    void masked_copy(int p, const double* b, double* r, cudaStream_t s) override
    {
        if (T_.local == 0) return;
        const long long L = T_.local * values(p);
        std::vector<Arg> a{element_list({nullptr, T_.local}, T_.local), vec(T_.face_code), vec(T_.edge_of),
                           vec(T_.vert_of), vec(T_.edge_dirichlet), vec(T_.vert_dirichlet), {b, L}, {r, L}};
        launch(masked_[p == 7 ? 0 : 1], a, T_.local, s);
    }

    void transfer(int p, int pc, bool prolong, bool add, const double* from, double* to, cudaStream_t s) override
    {
        if (T_.local == 0) return;
        const bool top = p == 7;
        const thrust::device_vector<double>& M = prolong ? (top ? i73_ : i31_) : (top ? i73t_ : i31t_);
        CUfunction fn = prolong ? (top ? prolong37_ : prolong13_)[add ? 1 : 0] : (top ? restrict73_ : restrict31_);
        const long long fine = T_.local * values(p), coarse = T_.local * values(pc);
        std::vector<Arg> a{element_list({nullptr, T_.local}, T_.local), vec(M), {from, prolong ? coarse : fine},
                           {to, prolong ? fine : coarse}};
        launch(fn, a, T_.local, s);
    }

    // Per-element partials of <a, z> / <z, z> on the p = 7 level (scratch: NV per element).
    template <bool AZ, bool ZZ>
    void dots(const double* z, const double* a, double* partials, cudaStream_t s)
    {
        constexpr int NV = AZ + ZZ;
        if (NV == 0 || T_.local == 0) return;
        const long long L = T_.local * values(7);
        std::vector<Arg> args{element_list({nullptr, T_.local}, T_.local), vec(T_.counting), {z, L}};
        if (AZ) args.push_back({a, L});
        args.push_back({z, 7});   // the kernels' unused Krylov-scalar argument
        args.push_back({partials, NV * T_.local});
        launch(dots_[AZ && ZZ ? 2 : (AZ ? 0 : 1)], args, T_.local, s);
    }

private:
    struct Matrices {
        thrust::device_vector<double> btil, dtil, w, d;
    };

    static long long values(int p) { return (long long)(p + 1) * (p + 1) * (p + 1); }
    static int degree_index(int p) { return p == 7 ? 0 : (p == 3 ? 1 : 2); }
    static const double* raw(const thrust::device_vector<double>& v) { return thrust::raw_pointer_cast(v.data()); }

    // The operator kernel's 1D matrices: Btil / Dtil with the face dimension padded to
    // p + 1 rows (as the solve does at p = 7).
    static void operators(int p, Matrices& m)
    {
        const fem::HoCvfemOperators ops = fem::buildHoCvfemOperators(p);
        const int n = p + 1;
        std::vector<double> btil(n * n, 0.0), dtil(n * n, 0.0);
        std::copy(ops.Btil.begin(), ops.Btil.end(), btil.begin());
        std::copy(ops.Dtil.begin(), ops.Dtil.end(), dtil.begin());
        m.btil = btil;
        m.dtil = dtil;
        m.w = std::vector<double>(ops.W.begin(), ops.W.end());
        m.d = std::vector<double>(ops.D.begin(), ops.D.end());
    }

    // I (fine x coarse) and its transpose, row-major.
    template <int PF, int PC>
    static void interpolation(const cellwise::Interpolation<PF, PC>& T, thrust::device_vector<double>& I,
                              thrust::device_vector<double>& It)
    {
        constexpr int nf = PF + 1, nc = PC + 1;
        std::vector<double> a(nf * nc), b(nf * nc);
        for (int i = 0; i < nf; ++i)
            for (int j = 0; j < nc; ++j) {
                a[i * nc + j] = T.I[i][j];
                b[j * nf + i] = T.I[i][j];
            }
        I = a;
        It = b;
    }

    const cellwise::UnstructuredTopology& T_;
    const double *G3_, *G1_;
    LaplacianPtx op3_, op1_;
    Matrices op3m_, op1m_;
    thrust::device_vector<double> i73_, i73t_, i31_, i31t_;
    CUfunction cheb_[3][3], masked_[2], restrict73_, restrict31_, prolong37_[2], prolong13_[2], dots_[3];
};

// One V-cycle as the preconditioner of the Krylov solvers: z = V(q), then the dot
// products in `scratch` (2 per local element), folded by the generated fold kernel
// for the hand Krylov loop.
template <class Multigrid>
struct MarsirPmg {
    const Multigrid* pmg;
    PmgPtx* ptx;
    BicgstabPtx* vec;
    const cellwise::UnstructuredTopology* T;
    double* scratch;

    template <bool AZ, bool ZZ>
    long long per_element(const double* q, double* z, const double* a, cudaStream_t stream) const
    {
        pmg->template vcycle<7>(q, z);
        ptx->dots<AZ, ZZ>(z, a, scratch, stream);
        return T->local;
    }

    template <bool AZ, bool ZZ>
    int operator()(const double* q, double* z, const double* a, double* partial, cudaStream_t stream) const
    {
        constexpr int NV = AZ + ZZ;
        const long long count = per_element<AZ, ZZ>(q, z, a, stream);
        if constexpr (NV == 0) return 0;
        else return vec->fold(NV, scratch, count, partial, stream);
    }
};

}  // namespace marsir
}  // namespace mars
